PRAGMA foreign_keys=ON;
CREATE TABLE plant(plant_id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE line(line_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plant(plant_id),name TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE machine(machine_id TEXT PRIMARY KEY,line_id TEXT NOT NULL REFERENCES line(line_id),name TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE shift(shift_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plant(plant_id),shift_date TEXT NOT NULL,code TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,planned_break_minutes INTEGER NOT NULL);
CREATE TABLE product(product_id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE machine_product(machine_id TEXT NOT NULL REFERENCES machine(machine_id),product_id TEXT NOT NULL REFERENCES product(product_id),ideal_cycle_seconds REAL NOT NULL CHECK(ideal_cycle_seconds>0),effective_from TEXT NOT NULL,effective_to TEXT,PRIMARY KEY(machine_id,product_id,effective_from));
CREATE TABLE production_order(order_id TEXT PRIMARY KEY,machine_id TEXT NOT NULL REFERENCES machine(machine_id),shift_id TEXT NOT NULL REFERENCES shift(shift_id),product_id TEXT NOT NULL REFERENCES product(product_id),status TEXT NOT NULL,planned_units INTEGER NOT NULL);
CREATE TABLE downtime_reason(reason_id TEXT PRIMARY KEY,description TEXT NOT NULL,category TEXT NOT NULL,planned TEXT NOT NULL);
CREATE TABLE state_event(event_id TEXT PRIMARY KEY,machine_id TEXT NOT NULL REFERENCES machine(machine_id),order_id TEXT NOT NULL REFERENCES production_order(order_id),shift_id TEXT NOT NULL REFERENCES shift(shift_id),start_at TEXT NOT NULL,end_at TEXT NOT NULL,state TEXT NOT NULL,reason_id TEXT REFERENCES downtime_reason(reason_id),issue_type TEXT);
CREATE TABLE production_count(count_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES production_order(order_id),machine_id TEXT NOT NULL REFERENCES machine(machine_id),shift_id TEXT NOT NULL REFERENCES shift(shift_id),at TEXT NOT NULL,delta_total INTEGER NOT NULL,correction_of TEXT REFERENCES production_count(count_id),issue_type TEXT);
CREATE TABLE quality_inspection(inspection_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES production_order(order_id),machine_id TEXT NOT NULL REFERENCES machine(machine_id),shift_id TEXT NOT NULL REFERENCES shift(shift_id),at TEXT NOT NULL,scrap_units INTEGER NOT NULL,rework_units INTEGER NOT NULL,issue_type TEXT);
CREATE TABLE oee_aggregate(aggregate_id TEXT PRIMARY KEY,machine_id TEXT NOT NULL REFERENCES machine(machine_id),shift_id TEXT NOT NULL REFERENCES shift(shift_id),planned_minutes REAL NOT NULL,run_minutes REAL NOT NULL,total_units INTEGER NOT NULL,good_units INTEGER NOT NULL,availability REAL NOT NULL,performance REAL NOT NULL,quality REAL NOT NULL,oee REAL NOT NULL,status TEXT NOT NULL);
